import { Logger } from '../../logger.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';
import { k8sIdOrNameArg } from './k8s.args.js';

export const k8sActivityCommand = defineCommand({
  description: 'List the recent activity of a Kubernetes cluster',
  since: null,
  options: {
    limit: defineOption({
      name: 'limit',
      schema: z.coerce.number().int().min(1).optional(),
      description: 'Maximum number of events to show',
      placeholder: 'limit',
    }),
    org: orgaIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const { limit, format, org: orgIdOrName } = options;

    const events = await k8sListActivity(orgIdOrName, clusterIdOrName, limit);

    switch (format) {
      case 'json':
        Logger.printJson(events);
        break;
      case 'human':
      default:
        if (events.length === 0) {
          Logger.println('🔎 No activity found for this cluster');
          return;
        }

        events.forEach((event) => {
          const date = event.date ?? event.createdAt ?? event.timestamp ?? '-';
          const state = event.state ?? event.status ?? '';
          const action = event.action ?? event.type ?? event.event ?? '';
          const details = event.message ?? event.cause ?? '';
          Logger.println([date, state && styleText('bold', state), action, details].filter(Boolean).join('  '));
        });
        break;
    }
  },
});
